function sysHud(dt){if(!H.b1)return;const[a,b]=W.ents,bw=H.bw;H.b1.setAttribute('width',bw*a.hp/a.max);const f=b.hp/b.max;H.b2.setAttribute('width',bw*f);H.b2.setAttribute('x',VW-20-bw*f);
