function doResize(){const w=innerWidth,h=innerHeight;document.documentElement.setAttribute('viewBox','0 0 '+w+' '+h);const fo=$('glhost');fo.setAttribute('width',w);fo.setAttribute('height',h);
 const cv=$('gl-canvas'),d=Math.min(devicePixelRatio||1,1.75);cv.width=Math.round(w*d);cv.height=Math.round(h*d);cv.style.width=w+'px';cv.style.height=h+'px';VW=w;VH=h;buildHUD()}
function attach(){addEventListener('keydown',e=>{const k=e.code;if(!KEYS[k]){const a=KMAP[0][k];if(a!==undefined&&!GM.menu)QUE.push([0,a]);const b=KMAP[1][k];if(b!==undefined&&GM.two&&!GM.menu)QUE.push([1,b])}KEYS[k]=true;
  if(k==='KeyC')GM.menu=!GM.menu,GM.midx=GM.cam;else if(k==='KeyV')setMode(GM.mode==='ROAM'?'FIGHT':'ROAM');else if(k==='KeyT')GM.goal=Math.floor(GM.tod*4+1)/4;else if(k==='KeyP')GM.pause=!GM.pause;
  else if(GM.menu){if(k==='ArrowUp'){GM.midx=(GM.midx+6)%7;setCam(GM.midx)}else if(k==='ArrowDown'){GM.midx=(GM.midx+1)%7;setCam(GM.midx)}else if(k==='Enter'||k==='Escape')GM.menu=false}
  if(/^(Space|Arrow|Slash|Comma|Period)/.test(k))e.preventDefault()});
 addEventListener('keyup',e=>{KEYS[e.code]=false});
 const cv=$('gl-canvas');cv.addEventListener('mousedown',e=>{if(GM.mode==='ROAM'&&document.pointerLockElement!==cv&&cv.requestPointerLock)try{cv.requestPointerLock()}catch(_){}QUE.push([0,e.button===2?'kick':'punch'])});
 document.addEventListener('mousemove',e=>{if(document.pointerLockElement===cv&&GM.mode==='ROAM')GM.ry-=e.movementX*.005});cv.addEventListener('contextmenu',e=>e.preventDefault());
 cv.addEventListener('wheel',e=>{e.preventDefault()},{passive:false})}
let _l=0;function loop(ts){requestAnimationFrame(loop);if(!_l)_l=ts;let dt=(ts-_l)/1000;_l=ts;dt=cl(dt,.001,.05);FPS+=(1/dt-FPS)*.06;W.t+=dt;
 sysInput(dt);sysFight(dt);sysFx(dt);if(!GM.pause&&!GM.menu)fxStep(dt);sysAnim(dt);sysCam(dt);if(gl)sysRender(dt);sysHud(dt);
 if(FPS<20&&GM.tier>0&&(W.at=(W.at||0)+dt)>3){W.at=0;GM.tier--;statusMsg('AUTO-PERF → '+TIERS[GM.tier].toLocaleString('en-US'))}else if(FPS>=20)W.at=0}
function boot(){try{initGL()}catch(e){console.error(e);statusMsg('WEBGL UNAVAILABLE')}
